            &HashMap::new(),
            None,
            &mut ui,
        )
        .unwrap();

    assert!(result.success);
    // Should show "Would run:" even though completed_check passes
    assert!(
        ui.has_message("Would run: echo hello"),
        "dry-run should ignore completed_check and show command, got: {:?}",
        ui.messages()
    );
    // Should not be skipped
    assert!(
        !result.steps[0].skipped,
        "dry-run step should not be marked as skipped"
    );
}

